/**
 * The ReadyCircle horizontal header logo (PNG), embedded as a data URI so
 * the PDF renderer needs no filesystem asset -- plan-engine is bundled into
 * the API and worker builds, where relative asset paths would not survive.
 *
 * Source: apps/web/src/assets/readycircle-logo-horizontal.png. Regenerate
 * with: [Convert]::ToBase64String([IO.File]::ReadAllBytes($path))
 */
export const READYCIRCLE_LOGO_PNG_DATA_URI =
  'data:image/png;base64,';
